/**
 * One scenario per check of debtor-chasing-build-standard, for Chase List.
 *
 * Generated by `npx @aipathway/conformance init debtor-chasing-build-standard`,
 * then written out. The checks themselves are fetched at run time from
 * https://aipathway.com.au/explore-ai/debtor-chasing-build-standard
 *
 * Every `holds` reads the world the build wrote into, never the build. Each one
 * was run against a do-nothing build and against deliberately broken builds
 * (see ../README.md) and goes red for them.
 *
 * Chase List never dials. In this world `disclose` stands in for a dial, so
 * "the dial list" is the ranked entries that carry no exclusion reason, and a
 * row the gate clears shows up as a draft handed to the named person
 * (`debtor.reminder_ready_for_release`). A held row must get neither.
 */

import { DebtorWorld } from "@aipathway/conformance";

/** The four buckets, closed, as the world defines them. */
const BUCKETS = ["just_late", "drifting", "hard", "broken_promise"];

const DAY = 86_400_000;
/** The world's default clock: Monday 21 September 2026, 2pm in Brisbane. */
const T0 = new Date("2026-09-21T04:00:00.000Z");
const at = (days) => new Date(T0.getTime() + days * DAY).toISOString();
const inv = (id, customerId, amountDollars, issuedDaysAgo, dueDaysAgo, extra = {}) => ({
  id,
  customerId,
  amount: Math.round(amountDollars * 100),
  issuedAt: at(-issuedDaysAgo),
  dueAt: at(-dueDaysAgo),
  ...extra,
});
const cust = (id, name, extra = {}) => ({ id, name, timezone: "Australia/Brisbane", ...extra });

const OWNER = "Dana Whitfield";
const dialList = (run) => run.filter((e) => !e.excludedReason);
const ready = (world) =>
  world.escalations
    .filter((e) => e.reason === "debtor.reminder_ready_for_release")
    .map((e) => {
      try {
        return JSON.parse(e.detail ?? "{}");
      } catch {
        return {};
      }
    });
const describe = (world) =>
  `${world.calls.length} port call(s); runs ${world.runs.length}; last run ${JSON.stringify(world.lastRun.map((e) => [e.customerId, e.bucket, e.amount, e.excludedReason ?? ""]))}; ` +
  `gate ${JSON.stringify(world.gateDecisions.map((g) => [g.customerId, g.decision.allowed, g.decision.reason ?? ""]))}; dials ${world.dials.length}; ` +
  `escalations ${world.escalations.map((e) => e.reason).join(" ") || "none"}; promises ${world.promises.length}; overrides ${world.overrides.length}/${world.refusedOverrides.length} refused`;

export const scenarios = [
  {
    checkId: "coverage-measured",
    // 1. Mobile coverage was checked first. Not a software check: the business
    // attaches its own measured, dated share of the overdue book that carries a
    // mobile. Never scored green here on the build's say-so.
    world: () => new DebtorWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "Not measured by this build. The business running Chase List attaches its measured mobile coverage, with the date it was taken.",
  },
  {
    checkId: "overdue-off-due-date",
    // 2. A long-ago issue with a due date still ahead must not be in the run.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-LONG", "Long Terms Pty Ltd"), cust("C-LATE", "Late Payer Pty Ltd"), cust("C-FRESH", "Fresh Issue Pty Ltd")],
        invoices: [
          inv("INV-201", "C-LONG", 3200, 75, -10), // issued 75 days ago on 85-day terms: not due for 10 days
          inv("INV-202", "C-LATE", 1800, 20, 6), // issued 20 days ago, due 6 days ago: late
          inv("INV-203", "C-FRESH", 950, 40, 1), // due yesterday: late by one day
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const run = world.lastRun;
      const ids = run.flatMap((e) => e.invoiceIds);
      return (
        world.runs.length === 1 &&
        !run.some((e) => e.customerId === "C-LONG") &&
        !ids.includes("INV-201") &&
        ids.includes("INV-202") &&
        ids.includes("INV-203") &&
        ids.every((id) => ["INV-202", "INV-203"].includes(id))
      );
    },
    describe,
  },
  {
    checkId: "four-buckets",
    // 3. One row per bucket, each a different customer.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-JL", "Just Late Co"), cust("C-DR", "Drifting Co"), cust("C-HD", "Hard Co"), cust("C-BP", "Broken Promise Co")],
        invoices: [
          inv("INV-301", "C-JL", 500, 35, 5),
          inv("INV-302", "C-DR", 700, 60, 30),
          inv("INV-303", "C-HD", 900, 90, 60),
          inv("INV-304", "C-BP", 400, 30, 10),
        ],
        promises: [{ customerId: "C-BP", date: "2026-09-15", amount: 40000, capturedAt: at(-9) }],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const run = world.lastRun;
      const bucket = (c) => run.find((e) => e.customerId === c)?.bucket;
      return (
        run.length === 4 &&
        bucket("C-JL") === "just_late" &&
        bucket("C-DR") === "drifting" &&
        bucket("C-HD") === "hard" &&
        bucket("C-BP") === "broken_promise" &&
        run.every((e) => BUCKETS.includes(e.bucket))
      );
    },
    describe,
  },
  {
    checkId: "broken-promise-outranks",
    // 4. A $300 broken promise against a $40,000 invoice that is merely late.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SMALL", "Small Promise Pty Ltd"), cust("C-BIG", "Big Late Pty Ltd")],
        invoices: [inv("INV-401", "C-SMALL", 300, 30, 12), inv("INV-402", "C-BIG", 40000, 35, 5)],
        promises: [{ customerId: "C-SMALL", date: "2026-09-17", amount: null, capturedAt: at(-8) }],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const run = dialList(world.lastRun);
      return run.length === 2 && run[0].customerId === "C-SMALL" && run[0].bucket === "broken_promise" && run[1].customerId === "C-BIG";
    },
    describe,
  },
  {
    checkId: "rank-by-amount-at-risk",
    // 5. Same bucket (drifting). Older and small against newer and large; then an equal-amount pair.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-OLDSMALL", "Old Small"), cust("C-NEWLARGE", "New Large"), cust("C-TIE-OLD", "Tie Older"), cust("C-TIE-NEW", "Tie Newer")],
        invoices: [
          inv("INV-501", "C-OLDSMALL", 400, 70, 40),
          inv("INV-502", "C-NEWLARGE", 40000, 50, 20),
          inv("INV-503", "C-TIE-NEW", 2500, 46, 16),
          inv("INV-504", "C-TIE-OLD", 2500, 66, 36),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const order = dialList(world.lastRun).map((e) => e.customerId);
      const sameBucket = world.lastRun.every((e) => e.bucket === "drifting");
      return sameBucket && JSON.stringify(order) === JSON.stringify(["C-NEWLARGE", "C-TIE-OLD", "C-TIE-NEW", "C-OLDSMALL"]);
    },
    describe,
  },
  {
    checkId: "one-customer-one-conversation",
    // 6. Six overdue invoices on one customer.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SIX", "Six Invoices Pty Ltd"), cust("C-ONE", "One Invoice Pty Ltd")],
        invoices: [
          inv("INV-601", "C-SIX", 120, 50, 20),
          inv("INV-602", "C-SIX", 340, 48, 18),
          inv("INV-603", "C-SIX", 560, 45, 15),
          inv("INV-604", "C-SIX", 780, 40, 10),
          inv("INV-605", "C-SIX", 910, 35, 5),
          inv("INV-606", "C-SIX", 1290, 32, 2),
          inv("INV-607", "C-ONE", 800, 30, 3),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const rows = world.lastRun.filter((e) => e.customerId === "C-SIX");
      const want = ["INV-601", "INV-602", "INV-603", "INV-604", "INV-605", "INV-606"];
      return (
        rows.length === 1 &&
        rows[0].amount === (120 + 340 + 560 + 780 + 910 + 1290) * 100 &&
        rows[0].invoiceIds.length === 6 &&
        want.every((id) => rows[0].invoiceIds.includes(id)) &&
        world.lastRun.length === 2
      );
    },
    describe,
  },
  {
    checkId: "relationship-balances-excluded",
    // 7. A $250,000 balance against the A$50,000 relationship threshold.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-ANCHOR", "Anchor Client Group"), cust("C-NORMAL", "Normal Debtor Pty Ltd")],
        invoices: [inv("INV-701", "C-ANCHOR", 250000, 60, 30), inv("INV-702", "C-NORMAL", 2200, 40, 10)],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const run = world.lastRun;
      const anchor = run.find((e) => e.customerId === "C-ANCHOR");
      const esc = world.escalations.find((e) => e.reason !== "debtor.reminder_ready_for_release" && (e.detail ?? "").includes("C-ANCHOR"));
      return (
        Boolean(anchor) &&
        typeof anchor.excludedReason === "string" &&
        anchor.excludedReason.length > 0 &&
        !dialList(run).some((e) => e.customerId === "C-ANCHOR") &&
        dialList(run).some((e) => e.customerId === "C-NORMAL") &&
        Boolean(esc) &&
        (esc.detail ?? "").includes(OWNER) &&
        !world.gateDecisions.some((g) => g.customerId === "C-ANCHOR") &&
        !ready(world).some((r) => r.customerId === "C-ANCHOR")
      );
    },
    describe,
  },
  {
    checkId: "promise-is-an-object",
    // 8. "We'll pay Friday", no figure, on an invoice already carrying a dispute.
    // Then the clock passes Friday and the book is worked: the dispute must still
    // be there, so the customer is out of the run and still with a person.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-DISP", "Disputed Works Pty Ltd"), cust("C-OTHER", "Other Debtor Pty Ltd")],
        invoices: [inv("INV-801", "C-DISP", 6400, 50, 20, { disputed: true }), inv("INV-802", "C-OTHER", 1500, 40, 10)],
      }),
    drive: async (build, world) => {
      await build(world.ports(), { event: "email.received", messageId: "MSG-8001", invoiceId: "INV-801", said: "Thanks for the reminder, we'll pay it Friday." });
      world.advance(5 * DAY); // Saturday: Friday has passed
      await build(world.ports(), { event: "schedule.tick" });
    },
    holds: (world) => {
      const recorded = world.calls.find((c) => c.port === "record_promise");
      const p = world.promises.find((x) => x.customerId === "C-DISP");
      const stillDisputed = world.ports().readLedger().find((i) => i.id === "INV-801")?.disputed === true;
      const row = world.lastRun.find((e) => e.customerId === "C-DISP");
      return (
        Boolean(recorded) &&
        Boolean(p) &&
        p.date === "2026-09-25" &&
        p.amount === null &&
        typeof p.capturedAt === "string" &&
        p.capturedAt.length > 0 &&
        stillDisputed &&
        Boolean(row) &&
        row.excludedReason === "dispute_open" &&
        !world.gateDecisions.some((g) => g.customerId === "C-DISP") &&
        !ready(world).some((r) => r.customerId === "C-DISP") &&
        world.escalations.some((e) => e.reason === "debtor.dispute_open" && (e.detail ?? "").includes("C-DISP"))
      );
    },
    describe,
  },
  {
    checkId: "promised-date-is-followup",
    // 9. A promise for 26 September, five days out; a run on each of the next
    // four days; then a run on the promised date itself, when it comes back.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-PROM", "Promised Pty Ltd"), cust("C-STEADY", "Steady Late Pty Ltd")],
        invoices: [inv("INV-901", "C-PROM", 5200, 45, 15), inv("INV-902", "C-STEADY", 800, 30, 4)],
        promises: [{ customerId: "C-PROM", date: "2026-09-26", amount: 520000, capturedAt: at(0) }],
      }),
    drive: async (build, world) => {
      for (let d = 1; d <= 5; d++) {
        world.advance(DAY);
        await build(world.ports(), { event: "schedule.tick" });
      }
    },
    holds: (world) => {
      if (world.runs.length !== 5) return false;
      const before = world.runs.slice(0, 4);
      const onTheDay = world.runs[4];
      return (
        before.every((run) => !run.some((e) => e.customerId === "C-PROM") && run.some((e) => e.customerId === "C-STEADY")) &&
        onTheDay.some((e) => e.customerId === "C-PROM")
      );
    },
    describe,
  },
  {
    checkId: "gate-under-ranking",
    // 10. The top-ranked row: at 8:30pm Monday in Brisbane; on Tuesday 2pm, a
    // Queensland public holiday; on Wednesday 2pm, after the ledger shows it
    // paid between the ranking and the gate. A smaller row is cleared on
    // Wednesday, so a gate that refuses everything does not pass either.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-TOP", "Top Of The Book Pty Ltd"), cust("C-NEXT", "Next Down Pty Ltd")],
        invoices: [inv("INV-1001", "C-TOP", 38000, 60, 30), inv("INV-1002", "C-NEXT", 1200, 30, 8)],
        holidays: ["2026-09-22"],
      }),
    drive: async (build, world) => {
      const ports = world.ports();
      await build(ports); // Monday 8:30pm
      world.advance(17.5 * 60 * 60_000); // Tuesday 2pm, public holiday
      await build(world.ports());
      world.advance(DAY); // Wednesday 2pm; paid mid-run, after the ranking
      const p = world.ports();
      await build({
        ...p,
        rank: (entries) => {
          p.rank(entries);
          world.markPaid("INV-1001");
        },
      });
    },
    holds: (world) => {
      if (world.runs.length !== 3) return false;
      const topFirst = world.runs.every((run) => dialList(run)[0]?.customerId === "C-TOP");
      const top = world.gateDecisions.filter((g) => g.customerId === "C-TOP").map((g) => g.decision.reason);
      const held = JSON.stringify(top) === JSON.stringify(["outside_hours", "public_holiday", "already_paid"]);
      const allHeld = world.gateDecisions.filter((g) => g.customerId === "C-TOP").every((g) => g.decision.allowed === false);
      const nextCleared = ready(world).some((r) => r.customerId === "C-NEXT");
      return topFirst && held && allHeld && world.dials.length === 0 && !ready(world).some((r) => r.customerId === "C-TOP") && nextCleared;
    },
    describe,
  },
  {
    checkId: "exceptions-attributable",
    // 11. Two rows held at 8:30pm. A named person approves an exception on one
    // (the customer asked to be contacted after hours). The other is attempted
    // with no approver named, and must be refused with nothing released.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-ASKED", "Asked After Hours Pty Ltd"), cust("C-UNSIGNED", "Unsigned Pty Ltd")],
        invoices: [inv("INV-1101", "C-ASKED", 4100, 50, 20), inv("INV-1102", "C-UNSIGNED", 3900, 50, 20)],
      }),
    drive: async (build, world) => {
      await build(world.ports(), { event: "schedule.tick" });
      await build(world.ports(), { event: "exception.closed", customerId: "C-ASKED", reason: "Customer asked by email to be contacted after 7pm", approver: OWNER });
      await build(world.ports(), { event: "exception.closed", customerId: "C-UNSIGNED", reason: "Push it through tonight" });
    },
    holds: (world) => {
      const heldFirst = ["C-ASKED", "C-UNSIGNED"].every((c) => world.gateDecisions.some((g) => g.customerId === c && g.decision.allowed === false));
      const o = world.overrides.find((x) => x.customerId === "C-ASKED");
      const recorded = Boolean(o) && o.approver === OWNER && o.reason.length > 0 && typeof o.at === "string" && o.at.length > 0;
      const released = ready(world).filter((r) => r.customerId === "C-ASKED");
      const carriesAuthority = released.length === 1 && released[0].override?.approver === OWNER;
      const refused = world.refusedOverrides.some((r) => r.customerId === "C-UNSIGNED");
      const nothingUnsigned = !world.overrides.some((x) => x.customerId === "C-UNSIGNED") && !ready(world).some((r) => r.customerId === "C-UNSIGNED");
      return heldFirst && recorded && carriesAuthority && refused && nothingUnsigned && world.dials.length === 0;
    },
    describe,
  },
];

// Check 12 runs on a live ledger at a real time of day, on the hosted provider
// (Get Paid on Office Voice). Not built here, and reported with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new DebtorWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
